// Imports
import '../../App.css';
import '../../Data.css'
import Footer from '../Footer';
import React, { useState } from 'react';
import axios from 'axios';
import { Line, Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend } from 'chart.js';
import { 
  Container, 
  Typography, 
  TextField, 
  Button, 
  Paper, 
  Grid,
  Box,
  CircularProgress,
  MenuItem,
  Slider
} from '@mui/material';
import { ThemeProvider, createTheme } from '@mui/material/styles';

// Registering Chart.js components
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend);

const theme = createTheme({
  palette: {
    primary: { main: '#7D267E' },
    secondary: { main: '#dc004e' },
  },
});

// Dropdown options for House Type and Suburb
const houseTypes = ["House", "Apartment", "Townhouse"];
const suburbs = ["Abbotsford", "Richmond", "Melbourne", "Fitzroy"];

function Data() {
  const [squareFootage, setSquareFootage] = useState('');
  const [bedrooms, setBedrooms] = useState('');
  const [bathrooms, setBathrooms] = useState('');
  const [garage, setGarage] = useState('');
  const [lotArea, setLotArea] = useState('');
  const [yearBuilt, setYearBuilt] = useState('');
  const [houseType, setHouseType] = useState('');
  const [suburb, setSuburb] = useState('');

  const [predictedPrice, setPredictedPrice] = useState(null);
  const [error, setError] = useState('');
  const [lineChartData, setLineChartData] = useState(null);
  const [barChartTypeData, setBarChartTypeData] = useState(null);
  const [barChartBedroomsData, setBarChartBedroomsData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(2); // Initial zoom level for the line chart

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setPredictedPrice(null);
    setLoading(true);

    const requestData = {
      ...(squareFootage && { square_footage: parseFloat(squareFootage) }),
      ...(bedrooms && { bedrooms: parseInt(bedrooms) }),
      ...(bathrooms && { bathrooms: parseInt(bathrooms) }),
      ...(garage && { garage: parseInt(garage) }),
      ...(lotArea && { lot_area: parseFloat(lotArea) }),
      ...(yearBuilt && { year_built: parseInt(yearBuilt) }),
      ...(houseType && { house_type: houseType }),
      ...(suburb && { suburb })
    };

    try {
      const response = await axios.post('http://localhost:8000/predict/', requestData);
      setPredictedPrice(response.data.predicted_price);

      // 1. Line Chart: Predicted Prices by Square Footage
      let baseSqFt = parseFloat(squareFootage) || 1000; // Default if no square footage input
      let stepSize = Math.pow(10, Math.floor(Math.log10(baseSqFt)) - zoomLevel); // Adjust step size based on zoom level
      stepSize = stepSize < 1 ? 1 : stepSize; // Ensure step size is at least 1

      const squareFootages = [];
      for (let i = baseSqFt - stepSize * 2; i <= baseSqFt + stepSize * 2; i += stepSize) {
        if (i > 0) squareFootages.push(Math.round(i));
      }

      const predictedPrices = await Promise.all(
        squareFootages.map(sf => 
          axios.post('http://localhost:8000/predict/', {...requestData, square_footage: sf })
            .then(res => res.data.predicted_price)
        )
      );

      const lineChartData = {
        labels: squareFootages,
        datasets: [
          {
            label: 'Predicted Prices',
            data: predictedPrices,
            borderColor: 'rgba(255, 99, 132, 1)',
            backgroundColor: 'rgba(255, 99, 132, 0.5)',
            fill: false,
            tension: 0.1,
            pointRadius: 4
          },
          {
            label: 'Your Prediction',
            data: [{ x: parseInt(squareFootage), y: response.data.predicted_price }],
            borderColor: 'rgb(250, 165, 18)',
            backgroundColor: 'rgba(255, 208, 17, 0.5)',
            pointRadius: 8,
            pointHoverRadius: 12,
            showLine: false // Highlight user's prediction
          }
        ]
      };
      setLineChartData(lineChartData);

      // 2. Bar Chart: Predicted Prices by House Type
      const predictionsByType = await Promise.all(
        houseTypes.map(type => 
          axios.post('http://localhost:8000/predict/', {...requestData, house_type: type })
            .then(res => res.data.predicted_price)
        )
      );
      setBarChartTypeData({
        labels: houseTypes,
        datasets: [
          { label: 'Predicted Prices by House Type', data: predictionsByType, backgroundColor: 'rgba(255, 159, 64, 0.5)' }
        ]
      });

      // 3. Bar Chart: Predicted Prices by Bedrooms
      const bedroomCounts = [1, 2, 3, 4, 5];
      const predictionsBedrooms = await Promise.all(
        bedroomCounts.map(bed => 
          axios.post('http://localhost:8000/predict/', {...requestData, bedrooms: bed })
            .then(res => res.data.predicted_price)
        )
      );
      setBarChartBedroomsData({
        labels: bedroomCounts,
        datasets: [
          { label: 'Predicted Prices by Bedrooms', data: predictionsBedrooms, backgroundColor: 'rgba(54, 162, 235, 0.5)' }
        ]
      });

    } catch (err) {
      setError('Error predicting price. Please try again.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className='datadiv'>
    <ThemeProvider className='datadiv' theme={theme}>
      <h1 className='data'>House Price Predictor</h1>
      <Container className='datadiv' maxWidth="md">
        <Box sx={{ my: 4 }}>
          <h1 gutterBottom>Enter your dream house details!</h1>
          <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
            <form onSubmit={handleSubmit}>
              <Grid container spacing={2}>
                {/* Form fields */}
                {/* ... */}
              </Grid>
            </form>
          </Paper>
          
          {predictedPrice && (
            <Paper elevation={3} sx={{ p: 3 }}>
              <Typography variant="h5" gutterBottom>
                Predicted Price: ${predictedPrice.toLocaleString()}
              </Typography>
              
              {/* Zoom Level Slider */}
              <Box sx={{ mt: 3 }}>
                <Typography gutterBottom>Zoom Level</Typography>
                <Slider
                  value={zoomLevel}
                  onChange={(e, newValue) => setZoomLevel(newValue)}
                  min={1}
                  max={4}
                  step={0.1}
                  valueLabelDisplay="auto"
                  sx={{ width: '100%' }}
                />

                {/* Line Chart for Predicted Prices */}
                {lineChartData && (
                  <Line 
                    data={lineChartData}
                    options={{
                      responsive: true,
                      plugins: {
                        legend: { position: 'top' },
                        title: { display: true, text: 'Predicted Prices by Square Footage' }
                      },
                      scales: { 
                        x: { title: { display: true, text: 'Square Footage' }}, 
                        y: { title: { display: true, text: 'Price ($)' }}
                      }
                    }}
                  />
                )}
                
                {/* Bar Chart for Price by House Type */}
                {barChartTypeData && (
                  <Bar 
                    data={barChartTypeData}
                    options={{
                      responsive: true,
                      plugins: {
                        legend: { position: 'top' },
                        title: { display: true, text: 'Price Predictions by House Type' }
                      },
                      scales: { 
                        x: { title: { display: true, text: 'House Type' }}, 
                        y: { title: { display: true, text: 'Predicted Price ($)' }}
                      }
                    }}
                  />
                )}

                {/* Bar Chart for Price by Bedrooms */}
                {barChartBedroomsData && (
                  <Bar 
                    data={barChartBedroomsData}
                    options={{
                      responsive: true,
                      plugins: {
                        legend: { position: 'top' },
                        title: { display: true, text: 'Price Predictions by Bedrooms' }
                      },
                      scales: { 
                        x: { title: { display: true, text: 'Number of Bedrooms' }}, 
                        y: { title: { display: true, text: 'Predicted Price ($)' }}
                      }
                    }}
                  />
                )}
              </Box>
            </Paper>
          )}
        </Box>
      </Container>
      <Footer />
    </ThemeProvider>
    </div>
  );
}

export default Data;
